func TestAuthHeaderTreatsBrowserCookiesAsRawCookieHeader(t *testing.T) {
	t.Parallel()

	cfg := &Config{
		AccessToken: "session=abc; theme=dark",
	}

	got := cfg.AuthHeader()
	if got != "session=abc; theme=dark" {
		t.Fatalf("AuthHeader() = %q, want raw cookie header", got)
	}
	if cfg.AuthSource != "browser" {
		t.Fatalf("AuthSource = %q, want %q", cfg.AuthSource, "browser")
	}
	if cookieHeader := cfg.BrowserCookieHeader(); cookieHeader != "session=abc; theme=dark" {
		t.Fatalf("BrowserCookieHeader() = %q, want raw cookie header", cookieHeader)
	}
}

func TestAuthHeaderTreatsJWTAsBearerToken(t *testing.T) {
	t.Parallel()

	token := strings.Repeat("a", 24) + "." + strings.Repeat("b", 100) + "." + strings.Repeat("c", 40)
	cfg := &Config{
		AccessToken: token,
	}

	got := cfg.AuthHeader()
	want := "Bearer " + token
	if got != want {
		t.Fatalf("AuthHeader() = %q, want %q", got, want)
	}
	if cfg.AuthSource != "bearer" {
		t.Fatalf("AuthSource = %q, want %q", cfg.AuthSource, "bearer")
	}
	if cookieHeader := cfg.BrowserCookieHeader(); cookieHeader != "" {
		t.Fatalf("BrowserCookieHeader() = %q, want empty for JWT", cookieHeader)
	}
}
